/// The selection is a URL Java can open. A scheme is required. A space is not.
fn selection_opens_as_url(text: &str) -> bool {
    if text.is_empty() || text.chars().any(|ch| ch.is_whitespace() || ch.is_control()) {
        return false;
    }
    let Some(scheme_end) = text.find(':') else {
        return false;
    };
    if scheme_end == 0 {
        return false;
    }
    let scheme = &text[..scheme_end];
    let mut chars = scheme.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if !first.is_ascii_alphabetic() {
        return false;
    }
    if !chars.all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '+' | '-' | '.')) {
        return false;
    }
    let rest = &text[scheme_end + 1..];
    !rest.is_empty()
        && !text
            .chars()
            .any(|ch| matches!(ch, '<' | '>' | '"' | '`' | '\\' | '^' | '{' | '}' | '|' | '[' | ']'))
}

/// Next scroll offset. Positive `lines` moves toward the tail. The floor is 0.
fn console_scroll_target(current: f32, lines: i32, row_h: f32) -> f32 {
    (current + lines as f32 * row_h).max(0.0)
}

/// Terminal lines for one menu motion. A page is the visible row count.
fn console_menu_lines(label: &str, rows: usize) -> i32 {
    let page = rows.max(1) as i32;
    match label {
        "Page Up" => -page,
        "Page Down" => page,
        "Line Up" => -1,
        "Line Down" => 1,
        _ => 0,
    }
}

/// Both corners of the buffer. Index 0 is the oldest line.
fn select_all_span(grid: &Grid) -> ((usize, usize), (usize, usize)) {
    let last_row = grid.history_len().saturating_sub(1);
    let last_col = grid.cols().saturating_sub(1);
    ((0, 0), (last_row, last_col))
}

/// Open as URL stays dark unless the highlight is a URL. Copy stays dark without a highlight.
/// Paste stays dark when the clipboard has no string. Page, line, and clear stay lit.
/// Clear on the alternate screen still leaves that grid as it stands.
/// @aa-sdd PK-0073 PK-0127 PK-0260 PK-0274 PK-0283 PK-4448 PK-4481 docs/specs/rust/aetheris/aetheris-client/src/chrome.spec.md
/// @aa-sdd PK-0466 docs/specs/java/org/aetheris/wire/wire.spec.md
/// @aa-sdd PK-3698 docs/specs/java/org/aetheris/ssh/ssh.spec.md
fn console_menu_gates(
    grid: &Grid,
    anchor: Option<(usize, usize)>,
    current: Option<(usize, usize)>,
    clipboard: Option<&str>,
) -> (bool, bool, bool, bool) {
    let url_on = match (anchor, current) {
        (Some(start), Some(end)) => {
            selection_opens_as_url(&selected_text(grid, start.0, start.1, end.0, end.1))
        }
        _ => false,
    };
    let copy_on = anchor.is_some() && current.is_some();
    let paste_on = clipboard.is_some();
    let buffer_on = true;
    (url_on, copy_on, paste_on, buffer_on)
}

/// The chord Java paints on the menu item. The label itself stays the menu string.
fn console_menu_tip(label: &str) -> Option<&'static str> {
    match label {
        "Copy" => Some("Ctrl+Shift+C"),
        "Paste" => Some("Ctrl+Shift+V"),
        "Clear Buffer" => Some("Ctrl+L"),
        "Page Up" => Some("Shift+Page Up"),
        "Page Down" => Some("Shift+Page Down"),
        "Line Up" => Some("Ctrl+Up"),
        "Line Down" => Some("Ctrl+Down"),
        _ => None,
    }
}

/// The nine JediTerm lines, then Import, then Select model. A dark line does not fire.
fn console_menu_pick(
    ui: &mut egui::Ui,
    url_on: bool,
    copy_on: bool,
    paste_on: bool,
    buffer_on: bool,
) -> Option<&'static str> {
    let mut picked = None;
    for label in CONSOLE_MENU {
        if CONSOLE_MENU_GAP.contains(&label) {
            ui.separator();
        }
        let on = match label {
            "Open as URL" => url_on,
            "Copy" => copy_on,
            "Paste" => paste_on,
            "Clear Buffer" | "Page Up" | "Page Down" | "Line Up" | "Line Down" => buffer_on,
            _ => true,
        };
        let mut response = ui.add_enabled(on, egui::Button::new(label));
        if label == SELECT_MODEL_LABEL {
            response = response.on_hover_text(SELECT_MODEL_TIP);
        }
        if label == EXPORT_SESSION_LABEL {
            response = response.on_hover_text(EXPORT_SESSION_TIP);
        }
        if label == TRANSFER_LABEL {
            response = response.on_hover_text(TRANSFER_CONSOLE_TIP);
        }
        if let Some(tip) = console_menu_tip(label) {
            response = response.on_hover_text(tip);
        }
        if response.clicked() {
            picked = Some(label);
            ui.close();
            break;
        }
    }
    picked
}

