    /// Vault, wire, air-gap, and engine. The canvas extra stays on the Aetheris strip.
    fn aetheris_status_facts(&self) -> String {
        let amwp = self
            .session
            .as_ref()
            .is_some_and(|session| session.mux_answered());
        let air = self
            .facts
            .as_ref()
            .map(|facts| facts.air_gap.as_str())
            .unwrap_or("");
        let engine = self
            .cards
            .get(self.focus)
            .map(|card| card.target.as_str())
            .unwrap_or("");
        aetheris_status_line(amwp, air, false, engine, "")
    }

