    /// `the_plate_waits_for_the_mux` keeps [`Plate::Ssh`] until the mux is up, and arms the console when a canvas drops.
    /// [`Plate::Ssh`] with the mux down and a wanted [`Plate::Aetheris`] stays on SSH and does not arm the console.
    /// The same pair with the mux up takes [`Plate::Aetheris`] and does not arm the console.
    /// [`Plate::Aetheris`] with the mux up and no pick stays on the canvas and does not arm the console.
    /// [`Plate::Aetheris`] with the mux up and a wanted [`Plate::Ssh`] takes SSH and arms the console.
    /// [`Plate::Aetheris`] with the mux down and no pick takes SSH and arms the console.
    /// [`Plate::Ssh`] with the mux down and no pick stays on SSH and does not arm the console.
    #[test]
    fn the_plate_waits_for_the_mux() {
        let stay = settle_plate(Plate::Ssh, false, Some(Plate::Aetheris));
        assert_eq!(stay.plate, Plate::Ssh);
        assert!(!stay.arm_console);

        let open = settle_plate(Plate::Ssh, true, Some(Plate::Aetheris));
        assert_eq!(open.plate, Plate::Aetheris);
        assert!(!open.arm_console);

        let hold = settle_plate(Plate::Aetheris, true, None);
        assert_eq!(hold.plate, Plate::Aetheris);
        assert!(!hold.arm_console);

        let keys = settle_plate(Plate::Aetheris, true, Some(Plate::Ssh));
        assert_eq!(keys.plate, Plate::Ssh);
        assert!(keys.arm_console);

        let dropped = settle_plate(Plate::Aetheris, false, None);
        assert_eq!(dropped.plate, Plate::Ssh);
        assert!(dropped.arm_console);

        let quiet = settle_plate(Plate::Ssh, false, None);
        assert_eq!(quiet.plate, Plate::Ssh);
        assert!(!quiet.arm_console);
    }

    /// `a_saved_aetheris_tab_waits_for_connect` opens on [`Plate::Ssh`] and waits when a stored canvas word is present.
    /// The opened plate is [`Plate::Ssh`].
    /// Restore is armed.
    /// The step does not land.
    /// Nothing is stored.
    /// A later step with the mux down and restore still armed stays on [`Plate::Ssh`].
    /// That step keeps restore, does not land, and stores nothing.
    #[test]
    fn a_saved_aetheris_tab_waits_for_connect() {
        let opened = open_product_tab(true);
        assert_eq!(opened.plate, Plate::Ssh);
        assert!(opened.restore);
        assert!(!opened.land);
        assert!(opened.store.is_none());
        let waiting = step_product_tab(opened.plate, false, opened.restore, None);
        assert_eq!(waiting.plate, Plate::Ssh);
        assert!(waiting.restore);
        assert!(!waiting.land);
        assert!(waiting.store.is_none());
    }

    /// `a_missing_word_opens_on_ssh` opens on [`Plate::Ssh`] and stays there when no canvas word was stored.
    /// Restore is not armed.
    /// A step with the mux up and restore off stays on [`Plate::Ssh`].
    /// That step does not land and stores nothing.
    /// A click of [`Plate::Ssh`] with restore off also stays on SSH and stores nothing.
    #[test]
    fn a_missing_word_opens_on_ssh() {
        let opened = open_product_tab(false);
        assert_eq!(opened.plate, Plate::Ssh);
        assert!(!opened.restore);
        let stay = step_product_tab(opened.plate, true, opened.restore, None);
        assert_eq!(stay.plate, Plate::Ssh);
        assert!(!stay.land);
        assert!(stay.store.is_none());
        let again = step_product_tab(Plate::Ssh, true, false, Some(Plate::Ssh));
        assert_eq!(again.plate, Plate::Ssh);
        assert!(again.store.is_none());
    }

    /// `a_tab_click_while_restore_is_armed_stores_ssh` stores [`TabWord::Ssh`] when SSH is clicked during an armed restore.
    /// A click with the mux down clears restore, does not land, and stores [`TabWord::Ssh`].
    /// The plate stays [`Plate::Ssh`].
    /// The same click with the mux up also clears restore, does not land, and stores [`TabWord::Ssh`].
    #[test]
    fn a_tab_click_while_restore_is_armed_stores_ssh() {
        let cancel = step_product_tab(Plate::Ssh, false, true, Some(Plate::Ssh));
        assert_eq!(cancel.plate, Plate::Ssh);
        assert!(!cancel.restore);
        assert!(!cancel.land);
        assert_eq!(cancel.store, Some(TabWord::Ssh));
        let same_frame = step_product_tab(Plate::Ssh, true, true, Some(Plate::Ssh));
        assert_eq!(same_frame.plate, Plate::Ssh);
        assert!(!same_frame.restore);
        assert!(!same_frame.land);
        assert_eq!(same_frame.store, Some(TabWord::Ssh));
    }

    /// `a_mux_restore_takes_aetheris_and_lands` takes [`Plate::Aetheris`] when the mux is up and restore is armed.
    /// The plate becomes [`Plate::Aetheris`].
    /// Restore clears.
    /// The step lands.
    /// Nothing is stored.
    /// The console is not armed.
    #[test]
    fn a_mux_restore_takes_aetheris_and_lands() {
        let land = step_product_tab(Plate::Ssh, true, true, None);
        assert_eq!(land.plate, Plate::Aetheris);
        assert!(!land.restore);
        assert!(land.land);
        assert!(land.store.is_none());
        assert!(!land.arm_console);
    }

    /// `a_manual_aetheris_click_stores_the_word_and_does_not_land` stores [`TabWord::Aetheris`] and does not land.
    /// A canvas click while restore is armed takes [`Plate::Aetheris`], clears restore, and does not land.
    /// That step stores [`TabWord::Aetheris`].
    /// A canvas click with restore already clear does the same store and still does not land.
    /// A canvas click while the plate is already [`Plate::Aetheris`] stays there, does not land, and stores nothing.
    /// A following SSH click takes [`Plate::Ssh`], arms the console, does not land, and stores [`TabWord::Ssh`].
    #[test]
    fn a_manual_aetheris_click_stores_the_word_and_does_not_land() {
        let manual = step_product_tab(Plate::Ssh, true, true, Some(Plate::Aetheris));
        assert_eq!(manual.plate, Plate::Aetheris);
        assert!(!manual.restore);
        assert!(!manual.land);
        assert_eq!(manual.store, Some(TabWord::Aetheris));
        let visit = step_product_tab(Plate::Ssh, true, false, Some(Plate::Aetheris));
        assert_eq!(visit.plate, Plate::Aetheris);
        assert!(!visit.land);
        assert_eq!(visit.store, Some(TabWord::Aetheris));
        let held = step_product_tab(Plate::Aetheris, true, false, Some(Plate::Aetheris));
        assert_eq!(held.plate, Plate::Aetheris);
        assert!(!held.land);
        assert!(held.store.is_none());
        let back = step_product_tab(Plate::Aetheris, true, false, Some(Plate::Ssh));
        assert_eq!(back.plate, Plate::Ssh);
        assert!(back.arm_console);
        assert!(!back.land);
        assert_eq!(back.store, Some(TabWord::Ssh));
    }

    /// `a_mux_drop_on_aetheris_arms_the_return` stores [`TabWord::Aetheris`] and waits on [`Plate::Ssh`] until the mux returns.
    /// A mux drop on [`Plate::Aetheris`] takes [`Plate::Ssh`] and arms the console.
    /// Restore is armed.
    /// The step does not land.
    /// The stored word is [`TabWord::Aetheris`].
    /// Another drop while restore is armed stays on [`Plate::Ssh`], keeps restore, and stores nothing.
    /// A mux-up step then takes [`Plate::Aetheris`], lands, clears restore, and stores nothing.
    /// A canvas click while the mux is down and restore is armed stays on [`Plate::Ssh`].
    /// That click keeps restore, stores nothing, and does not land.
    #[test]
    fn a_mux_drop_on_aetheris_arms_the_return() {
        let bounce = step_product_tab(Plate::Aetheris, false, false, None);
        assert_eq!(bounce.plate, Plate::Ssh);
        assert!(bounce.arm_console);
        assert!(bounce.restore);
        assert!(!bounce.land);
        assert_eq!(bounce.store, Some(TabWord::Aetheris));
        let again = step_product_tab(bounce.plate, false, bounce.restore, None);
        assert_eq!(again.plate, Plate::Ssh);
        assert!(again.restore);
        assert!(again.store.is_none());
        let land = step_product_tab(again.plate, true, again.restore, None);
        assert_eq!(land.plate, Plate::Aetheris);
        assert!(land.land);
        assert!(!land.restore);
        assert!(land.store.is_none());
        let blocked = step_product_tab(Plate::Ssh, false, true, Some(Plate::Aetheris));
        assert_eq!(blocked.plate, Plate::Ssh);
        assert!(blocked.restore);
        assert!(blocked.store.is_none());
        assert!(!blocked.land);
    }

